<?php $layout='layouts.app'; use App\Components\Breadcrumb; use App\Components\Button; use App\Components\Input; use App\Components\Select; $isEdit=$teacher!==null; $action=$isEdit?'/teachers/'.$teacher['id']:'/teachers'; $gender=['male'=>'Male','female'=>'Female']; ?>
<?= Breadcrumb::render([['label'=>'Teachers','href'=>'/teachers'],['label'=>$isEdit?'Edit teacher':'Add teacher']]) ?>
<h1><?= $isEdit?'Edit teacher':'Add a teacher' ?></h1>
<div class="card" style="max-width:760px;margin-top:var(--space-4)"><div class="card-body"><form action="<?= e($action) ?>" method="POST"><?= csrf() ?><div class="form-row"><?= Input::render('first_name','First name',value:old('first_name',$teacher['first_name']??''),required:true,errors:$errors) ?><?= Input::render('last_name','Last name',value:old('last_name',$teacher['last_name']??''),required:true,errors:$errors) ?><?= Select::render('gender',$gender,'Gender',old('gender',$teacher['gender']??''),placeholder:'Not specified',errors:$errors) ?></div><div class="form-row"><?= Input::render('employee_no','Employee no.',value:old('employee_no',$teacher['employee_no']??''),attrs:$isEdit?['readonly'=>'readonly']:[],required:true,errors:$errors) ?><?= Input::render('phone','Phone',value:old('phone',$teacher['phone']??''),errors:$errors) ?><?= Input::render('email','Email',type:'email',value:old('email',$teacher['email']??''),errors:$errors) ?></div><div class="form-row"><?= Select::render('department_id',array_column($departments,'name','id'),'Department',old('department_id',$teacher['department_id']??''),placeholder:'None',errors:$errors) ?><?= Input::render('joined_on','Joined on',type:'date',value:old('joined_on',$teacher['joined_on']??date('Y-m-d')),errors:$errors) ?><?= Input::render('employment_type','Employment type',value:old('employment_type',$teacher['employment_type']??''),errors:$errors) ?></div><div style="margin-top:var(--space-5)"><?= Button::primary($isEdit?'Save changes':'Add teacher',type:'submit') ?> <?= Button::outline('Cancel',href:'/teachers') ?></div></form></div></div>
